import json, re
from pathlib import Path

DATA = Path('admission_webapp/src/data')
varsity = json.load(open(DATA / 'varsity_bank.json'))
medical = json.load(open(DATA / 'medical_bank.json'))
weeks = json.load(open(DATA / 'weeks.json'))

def norm(t):
    return re.sub(r'\W+', '', re.sub(r'^\[[^\]]*\]', '', str(t or '')))[:80]

def make_q(qid, week_id, subject, chapter, track, origin, q, opts, ans, exp, speed_hack, trap, repeat_count=2, prob='92% High-Yield Core'):
    return {
        'id': qid,
        'week_id': week_id,
        'subject': subject,
        'chapter': chapter,
        'track': track,
        'origin': origin,
        'q': f'[{origin}] {q}',
        'question': f'[{origin}] {q}',
        'opts': opts,
        'options': opts,
        'ans': ans,
        'correct_index': ans,
        'exp': exp,
        'explanation': exp,
        'trap': trap,
        'trap_insight': trap,
        'trap_alert': trap,
        'speed_hack': speed_hack,
        'yield_stars': 4,
        'probability': prob,
        'repeat_count': repeat_count,
        'tag': 'High-Yield Core',
        'origin_badge': origin,
        'bank_type': track,
    }

