existing_ids = {x['id'] for x in varsity + medical}
existing_v = {norm(x.get('q') or x.get('question')) for x in varsity}
existing_m = {norm(x.get('q') or x.get('question')) for x in medical}

def add_items(target, seen_text, items, prefix, subject, track):
    added = 0
    for idx, (wk, ch, org, q, opts, ans, exp, sh, tr) in enumerate(items, 1):
        qid = f'{prefix}_{wk}_{idx:02d}'
        while qid in existing_ids:
            qid += '_x'
        if norm(q) in seen_text:
            continue
        existing_ids.add(qid)
        seen_text.add(norm(q))
        target.append(make_q(qid, wk, subject, ch, track, org, q, opts, ans, exp, sh, tr))
        added += 1
    return added

a1 = add_items(varsity, existing_v, VAR_BANGLA, 'var_ban', 'Bangla', 'varsity')
